<?php
/** Slice 2 proof — the document page and its actions (spec "Proof" 7, 10, 11): the preview per kind, rename, describe, move (the picker; too little on the target → 403), copy sharing the blob, locks (lock, another's version refused, unlock by the holder, break by a manager with the holder told). */
require __DIR__ . '/lib.php';
$seed = seed_store();
$contracts = $seed['contracts'];
$board = $seed['board_root'];
$priyaRoot = root_of(26);
$png = fx_dir() . '/photo.png'; $im = imagecreatetruecolor(300, 200); imagefill($im, 0, 0, imagecolorallocate($im, 200, 60, 60)); imagepng($im, $png); imagedestroy($im);
$md = fx_write('readme.md', "# Title\n\nSome **bold** and *em* text with <script>alert(1)</script> inside.\n\n- one\n- two\n\n```\ncode here\n```\n");
$csv = fx_write('table.csv', "name,amount\nAcme,100\nBeta,200\n" . implode("\n", array_map(static fn (int $i): string => "row$i,$i", range(1, 250))) . "\n");
$pdf = pdf_fixture('brief.pdf');
$docx = fx_docx('memo.docx', [['h1', 'Memo heading'], ['p', fx_para(4, 1200)]]);
$txt = fx_write('plain.txt', fx_para(6, 800));
$ids = [];
foreach (['png' => $png, 'md' => $md, 'csv' => $csv, 'pdf' => $pdf, 'docx' => $docx, 'txt' => $txt] as $k => $p) { $u = upload_file(27, $contracts, $p); $ids[$k] = (int) ($u['finish']['json']['record_id'] ?? 0); }
ok(min($ids) > 0, 'six documents of six kinds uploaded');
worker('extract_text');

echo "1. The document page and its preview\n";
$r = page(actor(26), '/documents/' . $ids['png']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="document-preview" data-mode="image"') && str_contains($r['body'], 'src="/d/' . $ids['png'] . '"'), 'a PNG previews inline');
$r = page(actor(26), '/documents/' . $ids['pdf']);
ok($r['code'] === 200 && str_contains($r['body'], 'data-mode="pdf"') && str_contains($r['body'], '<iframe src="/d/' . $ids['pdf']), 'a PDF in the browser\'s viewer (an iframe of the gate)');
$r = page(actor(26), '/documents/' . $ids['md']);
ok($r['code'] === 200 && str_contains($r['body'], 'data-mode="markdown"') && str_contains($r['body'], '<strong>bold</strong>') && !str_contains($r['body'], '<script>alert(1)') && str_contains($r['body'], '&lt;script&gt;alert(1)'), 'Markdown rendered — and a <script> in it is text');
$r = page(actor(26), '/documents/' . $ids['csv']);
preg_match('#<table[^>]*id="document-preview-csv">(.*?)</table>#s', $r['body'], $csvTable);
ok($r['code'] === 200 && str_contains($r['body'], 'data-mode="csv"') && str_contains($r['body'], '<th>name</th>') && substr_count($csvTable[1] ?? '', '<tr>') === 200 && str_contains($r['body'], 'first 200 rows'), 'a CSV as a table of the first 200 rows');
$r = page(actor(26), '/documents/' . $ids['docx']);
ok($r['code'] === 200 && str_contains($r['body'], 'data-mode="extracted"') && str_contains($r['body'], 'Memo heading') && str_contains($r['body'], 'Download to open'), 'a DOCX shows the extracted text with Download to open');
$r = page(actor(26), '/documents/' . $ids['txt']);
ok($r['code'] === 200 && str_contains($r['body'], 'data-mode="text"'), 'a text file as text');
ok(str_contains($r['body'], 'id="versions-table"') && str_contains($r['body'], 'id="lock-state"') && str_contains($r['body'], 'id="document-download-btn"') && str_contains($r['body'], 'id="document-timeline"'), 'the versions table, the lock state, the download button and the trail are on the page');
ok(str_contains($r['body'], 'Text: ') && str_contains($r['body'], 'characters'), 'the extraction sentence names the characters read');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'document.open' AND document_id = :d AND actor_member_id = 26", ['d' => $ids['txt']]) === 1, 'opening the page logs document.open once');
ok(page(actor(31), '/documents/' . $ids['txt'])['code'] === 404 && page(actor(29), '/documents/' . $ids['txt'])['code'] === 404, 'a member outside the group and a guest: 404');
$j = get_json(26, '/documents/' . $ids['md'])['json']['data'] ?? [];
ok(isset($j['document'], $j['preview'], $j['versions'], $j['may'], $j['extraction'], $j['timeline']) && $j['preview']['mode'] === 'markdown' && !isset($j['document']['storage_path']) && $j['document']['my_level'] === 'edit', 'the page\'s JSON: document, preview (its mode), versions, may, extraction, timeline; never a storage path');

echo "2. Rename, describe, move, copy\n";
$r = post(27, '/documents/save.php', ['document' => $ids['txt'], 'name' => 'plain-renamed.txt']);
ok($r['code'] === 302 && doc_row($ids['txt'])['name'] === 'plain-renamed.txt' && last_event('document.rename')['document_id'] == $ids['txt'], 'document_rename lands on the document; logged');
$r = post_j(27, '/documents/save.php', ['document' => $ids['txt'], 'name' => 'readme.md']);
ok($r['code'] === 422 && ($r['json']['error']['fields']['name'] ?? '') !== '', 'a taken name: 422 on the field');
$r = post_j(27, '/documents/save.php', ['document' => $ids['txt'], 'name' => 'a/b.txt']);
ok($r['code'] === 422, 'a slash in a name: 422');
$r = post_j(27, '/documents/save.php', ['document' => $ids['txt'], 'description' => 'The plain one.']);
ok($r['code'] === 200 && doc_row($ids['txt'])['description'] === 'The plain one.' && ($r['json']['did'] ?? '') === 'Saved the description', 'document_describe (the name stays)');
$r = get_json(27, '/documents/' . $ids['txt'] . '/move');
ok($r['code'] === 200 && ($r['json']['data']['picker']['source'] ?? '') === 'folder', 'the move screen names the folder picker');
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
pdo()->prepare("INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = :b), :b, 'Archive', 27, 27)")->execute(['b' => $board]);
$archive = (int) one("SELECT id FROM folders WHERE parent_id = :b AND name = 'Archive'", ['b' => $board]);
$r = post_j(27, '/documents/move.php', ['document' => $ids['txt'], 'target_folder' => $archive]);
ok($r['code'] === 200 && (int) doc_row($ids['txt'])['folder_id'] === $archive && json_decode(last_event('document.move')['before'], true)['folder_id'] === $contracts, 'document_move into a sibling folder; logged with before/after');
$r = post_j(26, '/documents/move.php', ['document' => $ids['txt'], 'target_folder' => $priyaRoot]);
ok($r['code'] === 200 && (int) doc_row($ids['txt'])['library_id'] === (int) one("SELECT id FROM libraries WHERE kind = 'personal' AND owner_member_id = 26") , 'a group member moves a group document into her own library (edit on it, add on the target); the library follows');
$r = post_j(26, '/documents/move.php', ['document' => $ids['txt'], 'target_folder' => $archive]);
ok($r['code'] === 200, '...and back');
pdo()->exec("INSERT INTO folder_access (folder_id, principal_kind, principal_id, level, granted_by) VALUES ($archive, 'member', 28, 'view', 27) ON CONFLICT DO NOTHING");
$r = post_j(28, '/documents/move.php', ['document' => $ids['txt'], 'target_folder' => root_of(28)]);
ok($r['code'] === 403, 'a viewer may not move a document (403 in words)');
pdo()->exec("INSERT INTO folder_access (folder_id, principal_kind, principal_id, level, granted_by) VALUES ($archive, 'member', 30, 'edit', 27) ON CONFLICT DO NOTHING");
$r = post_j(30, '/documents/move.php', ['document' => $ids['txt'], 'target_folder' => $contracts]);
ok($r['code'] === 403 || $r['code'] === 404, 'an editor of the folder may not move into a target where they hold nothing (' . $r['code'] . ')');
$blob = (int) one('SELECT blob_id FROM document_versions WHERE id = (SELECT current_version_id FROM documents WHERE id = :d)', ['d' => $ids['pdf']]);
$ref0 = (int) one('SELECT ref_count FROM blobs WHERE id = :b', ['b' => $blob]);
$r = post_j(26, '/documents/copy.php', ['document' => $ids['pdf'], 'target_folder' => $priyaRoot]);
$copyId = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && $copyId > 0 && ($r['json']['location'] ?? '') === '/documents/' . $copyId . '?notice=copied', 'document_copy: a new document, the location the copy\'s');
$c = doc_row($copyId);
ok((int) $c['owner_member_id'] === 26 && (int) $c['folder_id'] === $priyaRoot && $c['sha256'] === doc_row($ids['pdf'])['sha256'] && (int) one('SELECT blob_id FROM document_versions WHERE document_id = :d', ['d' => $copyId]) === $blob && (int) one('SELECT ref_count FROM blobs WHERE id = :b', ['b' => $blob]) === $ref0 + 1, '...mine, the same blob, ref_count up by one');
ok(one('SELECT source FROM document_versions WHERE document_id = :d', ['d' => $copyId]) === 'copy', '...the version\'s source is copy');
$r = post_j(26, '/documents/copy.php', ['document' => $ids['pdf'], 'target_folder' => $priyaRoot]);
ok($r['code'] === 200 && doc_row((int) $r['json']['record_id'])['name'] === 'brief (2).pdf', 'a second copy into the same folder is "brief (2).pdf"');

echo "3. Locks\n";
$r = post_j(26, '/documents/lock.php', ['document' => $ids['md']]);
ok($r['code'] === 200 && (int) doc_row($ids['md'])['locked_by'] === 26 && str_contains($r['json']['did'] ?? '', 'Locked'), 'Priya locks a group document');
$r = post_j(27, '/documents/lock.php', ['document' => $ids['md']]);
ok($r['code'] === 409 && str_contains($r['json']['error']['message'] ?? '', 'Locked by SMOKE Priya'), 'Marco cannot lock it: 409 naming the holder');
$u = upload_file(27, $contracts, $md, ['document_id' => $ids['md']]);
ok($u['start']['code'] === 423 && ($u['start']['json']['error']['code'] ?? '') === 'locked', 'another\'s version while locked: 423 locked');
$r = post_j(27, '/documents/save.php', ['document' => $ids['md'], 'name' => 'x.md']);
ok($r['code'] === 423, 'another\'s rename while locked: 423');
$r = post_j(27, '/documents/unlock.php', ['document' => $ids['md']]);
ok($r['code'] === 409, 'Marco cannot unlock Priya\'s lock (409)');
$r = post_j(26, '/documents/unlock.php', ['document' => $ids['md']]);
ok($r['code'] === 200 && doc_row($ids['md'])['locked_by'] === null, 'the holder unlocks');
post_j(26, '/documents/lock.php', ['document' => $ids['md']]);
$r = post_j(28, '/documents/lock-break.php', ['document' => $ids['md']]);
ok(in_array($r['code'], [403, 404], true), 'a viewer cannot break it');
$r = post_j(27, '/documents/lock-break.php', ['document' => $ids['md']]);
ok($r['code'] === 200 && doc_row($ids['md'])['locked_by'] === null && last_event('document.lock_break') !== null, 'the owner (manage) breaks it; logged document.lock_break');
ok((int) one("SELECT count(*) FROM notifications WHERE member_id = 26 AND kind = 'lock_broken'") === 1, '...the holder is told (lock_broken)');
$r = page(actor(26), '/documents/' . $ids['md']);
ok(str_contains($r['body'], 'id="document-lock-btn"') && !str_contains($r['body'], 'id="document-unlock-btn"'), 'the page offers Lock again');
finish();
